  `item_purchased` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `purchase_amount_usd` decimal(10,2) NOT NULL,
  `location` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `size` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `color` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `season` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `review_rating` decimal(3,1) NOT NULL,
  `subscription_status` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shipping_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `discount_applied` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `previous_purchases` int NOT NULL,
  `payment_method` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `frequency_of_purchases` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `rating_imputed` tinyint NOT NULL DEFAULT '0',
  `age_group` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `spending_category` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `rating_category` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `loyalty_category` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `discount_flag` tinyint NOT NULL,
  `subscription_flag` tinyint NOT NULL,
  PRIMARY KEY (`customer_id`),
  KEY `idx_cd_category` (`category`),
  KEY `idx_cd_age_group` (`age_group`),
  CONSTRAINT `chk_cd_age` CHECK ((`age` between 0 and 120)),
  CONSTRAINT `chk_cd_age_group` CHECK ((`age_group` in (_utf8mb4'18-24',_utf8mb4'25-34',_utf8mb4'35-44',_utf8mb4'45-54',_utf8mb4'55-64',_utf8mb4'65+'))),
  CONSTRAINT `chk_cd_amount` CHECK ((`purchase_amount_usd` >= 0)),
  CONSTRAINT `chk_cd_flags` CHECK (((`rating_imputed` in (0,1)) and (`discount_flag` in (0,1)) and (`subscription_flag` in (0,1)))),
  CONSTRAINT `chk_cd_rating` CHECK ((`review_rating` between 0 and 5)),
  CONSTRAINT `chk_cd_subscription` CHECK ((`subscription_status` in (_utf8mb4'Yes',_utf8mb4'No')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
