--
-- Table structure for table `customer_segments`
--

DROP TABLE IF EXISTS `customer_segments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `customer_segments` (
  `customer_id` int NOT NULL,
  `previous_purchases` int NOT NULL,
  `purchase_amount_usd` decimal(10,2) NOT NULL,
  `frequency_of_purchases` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `L_Score` tinyint NOT NULL,
  `F_Score` tinyint NOT NULL,
  `M_Score` tinyint NOT NULL,
  `LFM_Score` tinyint NOT NULL,
  `Customer_Segment` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`customer_id`),
  KEY `idx_seg_segment` (`Customer_Segment`),
  CONSTRAINT `fk_segments_customer` FOREIGN KEY (`customer_id`) REFERENCES `customer_data` (`customer_id`),
  CONSTRAINT `chk_seg_scores` CHECK (((`L_Score` between 1 and 5) and (`F_Score` between 1 and 5) and (`M_Score` between 1 and 5) and (`LFM_Score` = ((`L_Score` + `F_Score`) + `M_Score`))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

