DROP TABLE IF EXISTS `kpi_registry`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kpi_registry` (
  `kpi_id` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `kpi_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `calculation_formula` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `dax_formula` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `data_source` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expected_value` decimal(12,2) NOT NULL,
  `unit` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`kpi_id`),
  UNIQUE KEY `uq_kpi_name` (`kpi_name`),
  CONSTRAINT `chk_kpi_id_format` CHECK (regexp_like(`kpi_id`,_utf8mb4'^KPI-[0-9]{3}$'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
