INSERT INTO `kpi_registry` VALUES ('KPI-001','Total Customers','Number of distinct customers in the cleaned customer dataset (one row per customer).','COUNT(DISTINCT customer_data.customer_id)','DISTINCTCOUNT(customer_data[customer_id])','customer_data.customer_id',3900.00,'customers'),('KPI-002','Total Revenue','Sum of the recorded purchase amount (USD) over all customers. One purchase value per customer; not transaction-level history.','SUM(customer_data.purchase_amount_usd)','SUM(customer_data[purchase_amount_usd])','customer_data.purchase_amount_usd',233081.00,'USD'),('KPI-003','Average Purchase Value','Average purchase_amount_usd per customer record. The data has one row per customer, so this equals average customer spend and average value per recorded purchase.','AVG(customer_data.purchase_amount_usd)','AVERAGE(customer_data[purchase_amount_usd])','customer_data.purchase_amount_usd',59.76,'USD per customer'),('KPI-004','Average Review Rating','Mean review rating (scale 0 to 5) after documented category-median imputation of 37 missing ratings.','AVG(customer_data.review_rating)','AVERAGE(customer_data[review_rating])','customer_data.review_rating',3.75,'rating out of 5'),('KPI-005','Customers With Subscription','Number of distinct customers whose subscription_status is Yes.','COUNT(DISTINCT customer_id) WHERE subscription_status = \'Yes\'','CALCULATE(DISTINCTCOUNT(customer_data[customer_id]), customer_data[subscription_status] = \"Yes\")','customer_data.customer_id, customer_data.subscription_status',1053.00,'customers');
